// Compiled floor clearance. Last paint wins; object bases override paint.
export const WAR_FLOOR_GRID=8,WAR_FLOOR_COLS=1025;
export const WAR_FLOOR_CLEARANCE=new Uint8Array(1050625);
const bytes=atob('');let offset=0;for(let i=0;i<bytes.length;i+=3){const n=bytes.charCodeAt(i)+(bytes.charCodeAt(i+1)<<8);WAR_FLOOR_CLEARANCE.fill(bytes.charCodeAt(i+2),offset,offset+n);offset+=n;}
